public int calculateCoins(int amount, int[] array){ 
    int coinsNeeded = 0; 
    for (int i = array.length - 1; i >= 0; i--){ 

        // Find the largest denomination 
        // which is smaller than amount 
        while (amount >= array[i]){ 
            amount = amount - array[i]; 
            coinsNeeded++; 
        } 
    } 
    return coinsNeeded; 
}

