def print_all_combinations(arr):
    n = len(arr)
    result = []
    def combinations(arr, start, end, index, r):
        if index == r: 
            result.append(list(arr[start : end + 1]))  
            return
        for i in range(start, end + 1): 
            arr[start], arr[i] = arr[i], arr[start]  
            combinations(arr, start + 1, end, index + 1, r) 
            arr[start], arr[i] = arr[i], arr[start] 

