{  
    int arr[] = {4,3,7,2,9,6};  
    int n = sizeof(arr)/sizeof(arr[0]);  

    sort(arr, n);  

    cout << "Sorted array: \n";  
    for (int i=0; i < n; i++)  
        cout << arr[i] << " ";  
    cout << endl;  
    return 0;  
}

