public int partition(int[] arr, int start, int end) {
  int pivot = arr[end];
  int i = start-1;

  for (int j = start; j < end; j++) {
    if (arr[j] <= pivot) {
      i++;
      swap(arr, i, j);
    }
  }

  swap(arr, i+1, end);

  return i+1;
}

