  public void push(int data){
    Node newNode = new Node(data);
    if(top == null){
      top = newNode;
    } else {
      newNode.next = top;
      top = newNode;
    }
  }

  public int pop(){
    if(top == null){
      throw new NoSuchElementException("Stack Underflow Error");
    }
    int data = top.data;
    top = top.next;
    return data;
  }

  public int peek(){
    if(top == null){
      throw new NoSuchElementException("Stack Underflow Error");
    }
    return top.data;
  }

