	            ++top;
	            arr[top] = x;
	        } else {
	            cout << "Stack overflow!" << endl;
	        }
	    }

	    int pop() {
	        if (top < 0) {
	            cout << "Stack underflow!" << endl;
	            return -1;
	        } else {
	            return arr[top--];
	        }
	    }

	    int topElement() {
	        if (top < 0) {
	            cout << "Stack underflow!" << endl;
	            return -1;
	        } else {
	            return arr[top];
	        }
	    }

	    int isEmpty() {
	        return top < 0;
	    }
};

