  print("You have nothing in your inventory.")

def quit_game():
  print("Thanks for playing!")
  return False

intro()
playing = True
while playing:
  command = input("What would you like to do? > ").lower()
  if command == 'help':
    help_command()
  elif command == 'north' or command == 'south' or command == 'west' or command == 'east':
