    // they cannot be anagrams
    if (strlen($s1) != strlen($s2)) { 
        return false; 
    } 

    // Create an array and assign value 0 to each character
    $count = array(); 
    for ($i = 0; $i < strlen($s1); $i++) { 
        $count[$s1[$i]] = 0; 
