def get_median(arr):
    sorted_arr = sorted(arr)
    length = len(sorted_arr)
    if length % 2 == 0:
        median1 = sorted_arr[int(length/2) - 1]
        median2 = sorted_arr[int(length/2)]
        median = (median1 + median2) / 2
    else:
        median = sorted_arr[int((length-1)/2)]
    return median

