var flag = false;
while (flag === false) {
    flag = true;
    for (var i=0; i<list.length -1; i++) {
        if (list[i] > list[i+1]) {
            var temp = list[i];
            list[i] = list[i+1];
            list[i+1] = temp;
            flag = false;
        }
    }
}
